#!/usr/bin/env bash
# Creates or updates the one draft release that .github/workflows/release-draft.yml owns: tag
# v$VERSION, target $GITHUB_SHA, notes generated by GitHub from the changes since the latest
# published release. The owned draft is the one whose notes contain $DRAFT_MARKER; every other
# draft and every published release is left alone.
#
# Inputs (environment): GH_TOKEN, GITHUB_REPOSITORY, GITHUB_SHA, VERSION, DRAFT_MARKER,
# GITHUB_STEP_SUMMARY (optional).
set -euo pipefail

if [ -z "${VERSION:-}" ]; then
  echo "::error::No version to name the draft release after."
  exit 1
fi

repo="repos/$GITHUB_REPOSITORY"
tag="v$VERSION"

# The latest published release (drafts and prereleases are never "latest"). None yet (404): let
# GitHub choose the range.
errors=$(mktemp)
if ! previous=$(gh api "$repo/releases/latest" --jq .tag_name 2>"$errors"); then
  if ! grep -q 'HTTP 404' "$errors"; then
    cat "$errors" >&2
    exit 1
  fi
  previous=""
fi
notes_args=(-f tag_name="$tag" -f target_commitish="$GITHUB_SHA")
if [ -n "$previous" ]; then
  notes_args+=(-f previous_tag_name="$previous")
fi
notes=$(gh api -X POST "$repo/releases/generate-notes" "${notes_args[@]}" --jq .body)
body="$notes"$'\n\n'"$DRAFT_MARKER"

draft_ids=$(gh api --paginate "$repo/releases?per_page=100" \
  --jq '.[] | select(.draft and ((.body // "") | contains(env.DRAFT_MARKER))) | .id')
draft_id=${draft_ids%%$'\n'*}

if [ -n "$draft_id" ]; then
  method=PATCH
  endpoint="$repo/releases/$draft_id"
else
  method=POST
  endpoint="$repo/releases"
fi

url=$(gh api -X "$method" "$endpoint" \
  -f tag_name="$tag" -f target_commitish="$GITHUB_SHA" -f name="$VERSION" \
  -F draft=true -f body="$body" --jq .html_url)

echo "Draft release $tag for $GITHUB_SHA (previous release ${previous:-none}): $url" \
  | tee -a "${GITHUB_STEP_SUMMARY:-/dev/null}"
